// ============================================
// Node-003: 解析配置
// ============================================
// 功能：
// 1. 将配置数组转换为config对象
// 2. 进行类型转换（字符串→数字/布尔）
// 3. 验证必填参数
// 4. 存储到workflow static data
// 5. 添加元数据（批次标识、时间戳等）
// ============================================

const items = $input.all();

console.log(`📊 开始解析配置，共 ${items.length} 个参数`);

// ============================================
// 1. 转换配置数组为对象
// ============================================
const configArray = items.map(item => item.json);
const config = {};

configArray.forEach(item => {
  const key = item['参数名'];
  let value = item['参数值'];

  // 类型转换
  // 数字类型
  if (['videosPerAccount', 'minLikeCount_incremental', 'minLikeCount_full',
       'minPlayCount_incremental', 'minPlayCount_full', 'minDuration',
       'maxDuration', 'daysToCrawl', 'dedupDays', 'accountDelay',
       'batchDelay', 'maxRetries'].includes(key)) {
    value = parseInt(value);
  }
  // 浮点数类型
  else if (['minInteractionRate_incremental', 'minInteractionRate_full',
            'similarityThreshold'].includes(key)) {
    value = parseFloat(value);
  }
  // 布尔类型
  else if (key === 'enableDedup') {
    value = value === 'TRUE' || value === true;
  }

  config[key] = value;
});

console.log(`✅ 配置解析完成：${JSON.stringify(config, null, 2)}`);

// ============================================
// 2. 验证必填参数
// ============================================
const requiredParams = [
  'mode', 'videosPerAccount', 'minLikeCount_incremental',
  'minLikeCount_full', 'minPlayCount_incremental', 'minPlayCount_full',
  'minDuration', 'maxDuration', 'daysToCrawl', 'enableDedup',
  'accountDelay', 'batchDelay', 'maxRetries'
];

const missingParams = requiredParams.filter(param => !config.hasOwnProperty(param));

if (missingParams.length > 0) {
  const error = `❌ 缺少必填参数: ${missingParams.join(', ')}`;
  console.error(error);
  throw new Error(error);
}

console.log(`✅ 参数验证通过，所有必填参数齐全`);

// ============================================
// 3. 添加元数据
// ============================================
const now = new Date();
const batchId = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}-${config.mode}`;

config.batchId = batchId;
config.startTime = now.toISOString();
config.accountsPerBatch = 10;  // 固定值：每10个账号批量写入一次

console.log(`📅 批次标识: ${batchId}`);
console.log(`⏰ 开始时间: ${config.startTime}`);

// ============================================
// 4. 根据mode选择对应的质量阈值
// ============================================
if (config.mode === 'incremental') {
  config.minLikeCount = config.minLikeCount_incremental;
  config.minPlayCount = config.minPlayCount_incremental;
  config.minInteractionRate = config.minInteractionRate_incremental;
  console.log(`🔄 使用增量模式阈值: 点赞≥${config.minLikeCount}, 播放≥${config.minPlayCount}`);
} else if (config.mode === 'full') {
  config.minLikeCount = config.minLikeCount_full;
  config.minPlayCount = config.minPlayCount_full;
  config.minInteractionRate = config.minInteractionRate_full;
  console.log(`📦 使用全量模式阈值: 点赞≥${config.minLikeCount}, 播放≥${config.minPlayCount}`);
} else {
  throw new Error(`❌ 无效的mode值: ${config.mode}，必须是incremental或full`);
}

// ============================================
// 5. 存储到workflow static data
// ============================================
// 关键：存储后所有节点都能访问，无需在数据流中携带
$workflow.staticData.config = config;

console.log(`💾 配置已存储到 workflow.staticData.config`);
console.log(`✅ Node-003 执行完成\n`);

// ============================================
// 6. 返回简化的输出（只包含关键信息）
// ============================================
return [{
  json: {
    mode: config.mode,
    batchId: config.batchId,
    startTime: config.startTime,
    videosPerAccount: config.videosPerAccount,
    minLikeCount: config.minLikeCount,
    minPlayCount: config.minPlayCount,
    accountsPerBatch: config.accountsPerBatch,
    message: "配置解析完成，已存储到static data"
  }
}];

// ============================================
// Node-005: 筛选启用账号
// ============================================
// 功能：
// 1. 过滤启用状态为TRUE的账号
// 2. 数据清洗和格式化
// 3. 验证必填字段
// 4. 统计账号数量
// ============================================

const items = $input.all();

console.log(`📊 开始筛选账号，总数: ${items.length}`);

// ============================================
// 1. 过滤和清洗账号数据
// ============================================
const enabledAccounts = items
  .map(item => item.json)
  .filter(account => {
    // 过滤条件：启用状态为TRUE
    const isEnabled = account['启用状态'] === 'TRUE' || account['启用状态'] === true;

    if (!isEnabled) {
      console.log(`⏭️  跳过禁用账号: ${account['账号昵称']}`);
      return false;
    }

    // 验证必填字段
    if (!account['sec_uid'] || !account['账号昵称']) {
      console.warn(`⚠️  账号数据不完整，已跳过: ${JSON.stringify(account)}`);
      return false;
    }

    return true;
  })
  .map((account, index) => {
    // 格式化账号数据（使用英文字段名）
    return {
      index: index + 1,  // 重新编号（从1开始）
      accountName: account['账号昵称'].trim(),
      secUid: account['sec_uid'].trim(),
      category: account['分类'] || '未分类',
      originalIndex: parseInt(account['序号']) || index + 1,

      // 不在这里添加config，由后续节点从static data读取
    };
  });

console.log(`✅ 筛选完成，启用账号数: ${enabledAccounts.length}`);

// ============================================
// 2. 验证账号列表
// ============================================
if (enabledAccounts.length === 0) {
  const error = '❌ 没有启用的账号，请检查"监控账号列表"中的启用状态';
  console.error(error);
  throw new Error(error);
}

// ============================================
// 3. 输出统计信息
// ============================================
const stats = {
  totalAccounts: items.length,
  enabledAccounts: enabledAccounts.length,
  disabledAccounts: items.length - enabledAccounts.length,
  categories: {}
};

// 统计各分类账号数
enabledAccounts.forEach(account => {
  const cat = account.category;
  stats.categories[cat] = (stats.categories[cat] || 0) + 1;
});

console.log(`\n📊 账号统计:`);
console.log(`  总账号数: ${stats.totalAccounts}`);
console.log(`  启用: ${stats.enabledAccounts}`);
console.log(`  禁用: ${stats.disabledAccounts}`);
console.log(`  分类统计: ${JSON.stringify(stats.categories, null, 2)}`);

// ============================================
// 4. 返回启用的账号列表
// ============================================
console.log(`✅ Node-005 执行完成\n`);

return enabledAccounts.map(account => ({
  json: account
}));

// ============================================
// Node-005.5-B: 合并采集进度
// ============================================
// 功能：
// 1. 获取账号列表（来自Node-005）
// 2. 获取采集进度表（来自Node-005.5-A）
// 3. 为每个账号附加progress对象
// 4. 构建完整的账号+进度数据
// ============================================

// 获取输入数据（使用n8n的多输入功能）
// 输入1：账号列表（来自Node-005）
// 输入2：采集进度表（来自Node-005.5-A）

const accountsInput = $('005: 筛选启用账号').all();  // 账号列表
const progressInput = $('005.5-A: 读取采集进度').all();  // 采集进度表

console.log(`📊 开始合并采集进度`);
console.log(`  账号数量: ${accountsInput.length}`);
console.log(`  进度记录数: ${progressInput.length}`);

// ============================================
// 1. 将进度表转换为Map（以secUid为key）
// ============================================
const progressMap = new Map();

if (progressInput && progressInput.length > 0) {
  progressInput.forEach(item => {
    const progress = item.json;
    const secUid = progress['sec_uid'] || progress['secUid'];

    if (secUid) {
      progressMap.set(secUid, {
        status: progress['采集状态'] || progress['status'] || '未开始',
        videosCollected: parseInt(progress['已采集视频数']) || 0,
        lastCrawlTime: progress['最后采集时间'] || null,
        batchId: progress['批次标识'] || null,
        failureCount: parseInt(progress['失败次数']) || 0,
        errorMessage: progress['错误信息'] || null
      });
    }
  });

  console.log(`✅ 进度表解析完成，有效记录: ${progressMap.size}`);
} else {
  console.log(`⚠️  采集进度表为空，所有账号将视为"未开始"`);
}

// ============================================
// 2. 从static data读取config
// ============================================
const config = $workflow.staticData.config;

if (!config) {
  throw new Error('❌ 无法从static data读取config，请检查Node-003');
}

console.log(`📦 当前模式: ${config.mode}`);
console.log(`📅 批次标识: ${config.batchId}`);

// ============================================
// 3. 为每个账号附加progress对象
// ============================================
const accountsWithProgress = accountsInput.map(item => {
  const account = item.json;
  const secUid = account.secUid;

  // 从progressMap中查找该账号的历史状态
  const historicalProgress = progressMap.get(secUid);

  if (historicalProgress) {
    // 有历史记录
    console.log(`  📌 ${account.accountName}: ${historicalProgress.status}, 失败${historicalProgress.failureCount}次`);

    return {
      ...account,
      progress: {
        hasHistory: true,
        status: historicalProgress.status,
        videosCollected: historicalProgress.videosCollected,
        lastCrawlTime: historicalProgress.lastCrawlTime,
        lastBatchId: historicalProgress.batchId,
        failureCount: historicalProgress.failureCount,
        errorMessage: historicalProgress.errorMessage
      }
    };
  } else {
    // 无历史记录，首次采集
    console.log(`  🆕 ${account.accountName}: 首次采集`);

    return {
      ...account,
      progress: {
        hasHistory: false,
        status: '未开始',
        videosCollected: 0,
        lastCrawlTime: null,
        lastBatchId: null,
        failureCount: 0,
        errorMessage: null
      }
    };
  }
});

// ============================================
// 4. 统计各状态账号数量
// ============================================
const statusStats = {
  未开始: 0,
  进行中: 0,
  已完成: 0,
  失败: 0
};

accountsWithProgress.forEach(account => {
  const status = account.progress.status;
  if (statusStats.hasOwnProperty(status)) {
    statusStats[status]++;
  }
});

console.log(`\n📊 账号状态统计:`);
console.log(`  未开始: ${statusStats['未开始']}`);
console.log(`  进行中: ${statusStats['进行中']}`);
console.log(`  已完成: ${statusStats['已完成']}`);
console.log(`  失败: ${statusStats['失败']}`);
console.log(`✅ Node-005.5 执行完成\n`);

// ============================================
// 5. 返回带进度的账号列表
// ============================================
return accountsWithProgress.map(account => ({
  json: account
}));

// ============================================
// Node-005.6: 智能过滤与重试策略
// ============================================
// 功能：
// 1. 根据mode和status决定是否处理账号
// 2. 实现智能重试机制
// 3. 过滤出需要采集的账号列表
// 4. 标记跳过和放弃的账号
// ============================================

const items = $input.all();

console.log(`📊 开始智能过滤，总账号数: ${items.length}`);

// ============================================
// 1. 从static data读取config
// ============================================
const config = $workflow.staticData.config;

if (!config) {
  throw new Error('❌ 无法从static data读取config');
}

const mode = config.mode;
const maxRetries = config.maxRetries || 3;

console.log(`📦 当前模式: ${mode}`);
console.log(`🔄 最大重试次数: ${maxRetries}`);

// ============================================
// 2. 定义过滤规则
// ============================================
const filterRules = {
  // ✅ 总是需要处理的情况
  shouldProcess: (account) => {
    const status = account.progress.status;
    const failureCount = account.progress.failureCount;

    // 规则1：未开始 → 总是处理
    if (status === '未开始') {
      return { process: true, reason: '首次采集' };
    }

    // 规则2：进行中 → 总是处理（可能是上次中断）
    if (status === '进行中') {
      return { process: true, reason: '继续未完成的采集' };
    }

    // 规则3：已完成
    if (status === '已完成') {
      if (mode === 'incremental') {
        // 增量模式：即使已完成也要处理（每天都采集新视频）
        return { process: true, reason: '增量模式：采集新视频' };
      } else {
        // 全量模式：已完成就跳过
        return { process: false, reason: '全量模式：已采集完成' };
      }
    }

    // 规则4：失败
    if (status === '失败') {
      if (failureCount >= maxRetries) {
        // 失败次数≥3：放弃
        return { process: false, reason: `失败${failureCount}次，已放弃` };
      } else {
        // 失败次数<3：重试
        return { process: true, reason: `失败${failureCount}次，准备重试` };
      }
    }

    // 默认：不处理
    return { process: false, reason: '未知状态' };
  }
};

// ============================================
// 3. 过滤账号并标记
// ============================================
const filteredAccounts = [];
const skippedAccounts = [];
const abandonedAccounts = [];

items.forEach(item => {
  const account = item.json;
  const decision = filterRules.shouldProcess(account);

  if (decision.process) {
    // 需要处理
    filteredAccounts.push({
      ...account,
      processingReason: decision.reason
    });
    console.log(`  ✅ ${account.accountName}: ${decision.reason}`);
  } else {
    // 跳过或放弃
    if (account.progress.failureCount >= maxRetries) {
      abandonedAccounts.push(account);
      console.log(`  ❌ ${account.accountName}: ${decision.reason}`);
    } else {
      skippedAccounts.push(account);
      console.log(`  ⏭️  ${account.accountName}: ${decision.reason}`);
    }
  }
});

// ============================================
// 4. 输出统计信息
// ============================================
console.log(`\n📊 过滤结果统计:`);
console.log(`  需要处理: ${filteredAccounts.length}`);
console.log(`  跳过: ${skippedAccounts.length}`);
console.log(`  放弃: ${abandonedAccounts.length}`);

// ============================================
// 5. 验证结果
// ============================================
if (filteredAccounts.length === 0) {
  console.warn(`⚠️  没有需要处理的账号`);
  console.log(`\n详细情况:`);
  console.log(`  总账号数: ${items.length}`);
  console.log(`  跳过账号: ${skippedAccounts.map(a => a.accountName).join(', ')}`);
  console.log(`  放弃账号: ${abandonedAccounts.map(a => a.accountName).join(', ')}`);

  // 如果是全量模式且所有账号都已完成，这是正常的
  if (mode === 'full' && skippedAccounts.length === items.length) {
    console.log(`\n✅ 全量模式：所有账号已采集完成，无需再次执行`);
  }

  // 返回空数组，后续节点会跳过
  return [];
}

console.log(`\n✅ Node-005.6 执行完成`);
console.log(`📝 将处理 ${filteredAccounts.length} 个账号\n`);

// ============================================
// 6. 返回需要处理的账号列表
// ============================================
return filteredAccounts.map(account => ({
  json: account
}));

// ============================================
// Node-007: 计算批次信息
// ============================================
// 功能：
// 1. 从static data读取config
// 2. 计算当前账号的批次编号
// 3. 计算进度百分比
// 4. 判断是否需要批次延迟
// 5. 为当前账号添加批次信息
// ============================================

const account = $input.first().json;

// ============================================
// 1. 获取循环变量
// ============================================
const currentIndex = $itemIndex;  // 当前索引（从0开始）
const totalAccounts = $totalItems;  // 总账号数

console.log(`\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`);
console.log(`📊 正在处理第 ${currentIndex + 1}/${totalAccounts} 个账号`);
console.log(`   账号名称: ${account.accountName}`);
console.log(`   处理原因: ${account.processingReason}`);

// ============================================
// 2. 从static data读取config
// ============================================
const config = $workflow.staticData.config;

if (!config) {
  throw new Error('❌ 无法从static data读取config');
}

const accountsPerBatch = config.accountsPerBatch || 10;  // 每批账号数

// ============================================
// 3. 计算批次信息
// ============================================
// 批次编号（从1开始）
const batchNumber = Math.floor(currentIndex / accountsPerBatch) + 1;

// 批次内的位置（从1开始）
const positionInBatch = (currentIndex % accountsPerBatch) + 1;

// 是否是批次的第一个账号
const isFirstInBatch = positionInBatch === 1;

// 是否是批次的最后一个账号
const isLastInBatch = positionInBatch === accountsPerBatch || (currentIndex === totalAccounts - 1);

// 是否是所有账号的最后一个
const isLastAccount = currentIndex === totalAccounts - 1;

console.log(`   批次信息: 第${batchNumber}批，批内第${positionInBatch}/${accountsPerBatch}个`);

// ============================================
// 4. 计算进度百分比
// ============================================
const progressPercent = Math.round((currentIndex + 1) / totalAccounts * 100);

console.log(`   总体进度: ${progressPercent}% (${currentIndex + 1}/${totalAccounts})`);

// ============================================
// 5. 确定延迟类型
// ============================================
let delayType = 'account';  // 默认：账号间延迟

if (isFirstInBatch && currentIndex > 0) {
  // 批次的第一个账号（且不是第一个批次）→ 批次间延迟
  delayType = 'batch';
  console.log(`   ⏰ 批次切换，将执行批次延迟: ${config.batchDelay}秒`);
} else if (!isFirstInBatch) {
  // 批次内的非第一个账号 → 账号间延迟
  console.log(`   ⏰ 将执行账号延迟: ${config.accountDelay}秒`);
} else {
  // 第一个账号，无需延迟
  console.log(`   ⏰ 首个账号，无需延迟`);
  delayType = 'none';
}

// ============================================
// 6. 构建输出对象
// ============================================
const outputData = {
  // 原始账号数据
  ...account,

  // 循环信息
  loopIndex: currentIndex,
  loopTotal: totalAccounts,

  // 批次信息
  batchNumber: batchNumber,
  positionInBatch: positionInBatch,
  isFirstInBatch: isFirstInBatch,
  isLastInBatch: isLastInBatch,
  isLastAccount: isLastAccount,

  // 进度信息
  progressPercent: progressPercent,

  // 延迟信息
  delayType: delayType,  // 'none' | 'account' | 'batch'

  // config（从static data读取，避免在数据流中传递）
  // 注意：不要在这里添加完整的config对象，后续节点从static data读取
};

console.log(`✅ Node-007 执行完成\n`);

// ============================================
// 7. 返回增强后的账号数据
// ============================================
return [{
  json: outputData
}];

// ============================================
// Node-008: 智能延迟
// ============================================
// 功能：
// 1. 根据delayType执行不同的延迟策略
// 2. 重试时使用指数退避算法
// 3. 随机化延迟时间，避免规律性请求
// 4. 输出延迟日志便于监控
// ============================================

const account = $input.first().json;

// ============================================
// 1. 从static data读取config
// ============================================
const config = $workflow.staticData.config;

if (!config) {
  throw new Error('❌ 无法从static data读取config');
}

const accountDelay = config.accountDelay || 3;  // 账号间延迟(秒)
const batchDelay = config.batchDelay || 10;      // 批次间延迟(秒)

// ============================================
// 2. 确定延迟时长
// ============================================
let delaySeconds = 0;

switch (account.delayType) {
  case 'none':
    // 第一个账号，无需延迟
    delaySeconds = 0;
    console.log(`⏰ 首个账号，立即开始`);
    break;

  case 'account':
    // 账号间延迟
    delaySeconds = accountDelay;
    console.log(`⏰ 账号间延迟: ${delaySeconds}秒`);
    break;

  case 'batch':
    // 批次间延迟
    delaySeconds = batchDelay;
    console.log(`⏰ 批次间延迟: ${delaySeconds}秒`);
    break;

  default:
    // 默认使用账号间延迟
    delaySeconds = accountDelay;
    console.warn(`⚠️  未知的延迟类型: ${account.delayType}，使用默认延迟`);
}

// ============================================
// 3. 重试时使用指数退避
// ============================================
const failureCount = account.progress.failureCount || 0;

if (failureCount > 0) {
  // 指数退避算法：
  // 第1次重试：延迟 × 2
  // 第2次重试：延迟 × 4
  // 第3次重试：延迟 × 8
  const backoffMultiplier = Math.pow(2, failureCount);
  const originalDelay = delaySeconds;
  delaySeconds = delaySeconds * backoffMultiplier;

  console.log(`🔄 重试账号（第${failureCount}次失败）`);
  console.log(`   应用指数退避: ${originalDelay}秒 × ${backoffMultiplier} = ${delaySeconds}秒`);
}

// ============================================
// 4. 添加随机抖动（±20%）
// ============================================
if (delaySeconds > 0) {
  // 随机因子：0.8 ~ 1.2
  const jitterFactor = 0.8 + (Math.random() * 0.4);
  const originalDelay = delaySeconds;
  delaySeconds = Math.round(delaySeconds * jitterFactor);

  console.log(`🎲 添加随机抖动: ${originalDelay}秒 × ${jitterFactor.toFixed(2)} = ${delaySeconds}秒`);
}

// ============================================
// 5. 执行延迟
// ============================================
if (delaySeconds > 0) {
  console.log(`⏱️  开始延迟 ${delaySeconds}秒...`);
  const startTime = Date.now();

  // 使用Promise实现延迟（n8n兼容方式）
  await new Promise(resolve => setTimeout(resolve, delaySeconds * 1000));

  const actualDelay = ((Date.now() - startTime) / 1000).toFixed(2);
  console.log(`✅ 延迟完成，实际用时: ${actualDelay}秒`);
} else {
  console.log(`⚡ 无需延迟，立即执行`);
}

// ============================================
// 6. 记录延迟信息到输出
// ============================================
const outputData = {
  ...account,

  // 延迟信息
  delayInfo: {
    type: account.delayType,
    configuredDelay: account.delayType === 'batch' ? batchDelay : accountDelay,
    actualDelay: delaySeconds,
    isRetry: failureCount > 0,
    retryCount: failureCount,
    hasJitter: delaySeconds > 0
  }
};

console.log(`✅ Node-008 执行完成\n`);

// ============================================
// 7. 返回账号数据（延迟已执行）
// ============================================
return [{
  json: outputData
}];
